// Parser le message d'entrée
const inputData = $input.all();
const rawMessage = inputData[0].json.body?.message || inputData[0].json.message || inputData[0].json.text || '';

console.log('Message reçu:', rawMessage);

// Parser les lignes
const lines = rawMessage.split('\n').filter(l => l.trim());

let customerName = '';
let productLines = '';
let paymentMethod = '';
let amount = 0;

lines.forEach(line => {
  const trimmedLine = line.trim();

  // Ligne client (première ligne ou avec "Client:")
  if (trimmedLine.includes('Client:')) {
    customerName = trimmedLine.replace('Client:', '').trim();
  } else if (!trimmedLine.includes('|') && !trimmedLine.toLowerCase().includes('paiement') && !trimmedLine.toLowerCase().includes('montant')) {
    if (!customerName) customerName = trimmedLine;
  }

  // Ligne produits (contient |)
  if (trimmedLine.includes('|')) {
    productLines = trimmedLine;
  }

  // Ligne paiement
  if (trimmedLine.toLowerCase().includes('paiement:')) {
    paymentMethod = trimmedLine.split(':')[1].trim();
  }

  // Ligne montant
  if (trimmedLine.toLowerCase().includes('montant:')) {
    const amountStr = trimmedLine.split(':')[1].trim().replace('€', '').replace(',', '.');
    amount = parseFloat(amountStr);
  }
});

// Parser les produits individuels
function parseProducts(productString) {
  if (!productString) return [];

  const items = productString.split('|');
  const products = [];

  items.forEach(item => {
    const match = item.trim().match(/^(.+?)\s+([\d-]+)\*([0-9.]+)\*([0-9.]+)$/);
    if (match) {
      const [, name, ref, qty, price] = match;
      products.push({
        name: name.trim(),
        reference: ref,
        quantity: parseFloat(qty),
        unit_price: parseFloat(price),
        description: `${name.trim()} (Réf: ${ref})`
      });
    }
  });

  return products;
}

const parsedProducts = parseProducts(productLines);
const calculatedTotal = parsedProducts.reduce((sum, product) => sum + (product.quantity * product.unit_price), 0);

return {
  customer_name: customerName,
  products: parsedProducts,
  payment_method: paymentMethod,
  amount_paid: amount,
  calculated_total: calculatedTotal,
  raw_message: rawMessage,
  search_term: customerName.split(' ').slice(0, 2).join(' ')
};

// Récupérer le customer_id
let customerId;
const searchResult = $('❓ Customer Exists?').item;
const createResult = $('👤 Create Customer').item;

if (createResult && createResult.json && createResult.json.id) {
  // Client créé
  customerId = createResult.json.id;
  console.log('Client créé avec ID:', customerId);
} else if (searchResult && searchResult.json && searchResult.json.data && searchResult.json.data.length > 0) {
  // Client trouvé
  customerId = searchResult.json.data[0].id;
  console.log('Client trouvé avec ID:', customerId);
} else {
  throw new Error('Impossible de récupérer le customer_id');
}

const parsedData = $('📝 Parse Message').item.json;

// Préparer les lignes de facture
const invoiceLines = parsedData.products.map(product => ({
  description: product.description,
  quantity: product.quantity,
  unit_price: product.unit_price,
  tax_rate: 20
}));

// Construire les données de facture
const invoiceData = {
  customer_id: customerId,
  invoice_date: new Date().toISOString().split('T')[0],
  due_date: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  currency: 'EUR',
  status: 'draft',
  lines: invoiceLines
};

console.log('Données facture préparées:', JSON.stringify(invoiceData, null, 2));

return {
  customer_id: customerId,
  invoice_data: invoiceData
};

// Récupérer les données nécessaires
const parsedData = $('📝 Parse Message').item.json;
const invoiceData = $('🧾 Create Invoice').item.json;

// Mapping des méthodes de paiement
const paymentMap = {
  'CB': 'credit_card',
  'CBx2': 'credit_card',
  'CBx3': 'credit_card',
  'CBx4': 'credit_card',
  'Espèces': 'cash',
  'Chèques': 'cheque',
  'Chèque': 'cheque',
  'Virement': 'transfer'
};

const paymentType = paymentMap[parsedData.payment_method] || 'cash';

const paymentData = {
  amount: parsedData.amount_paid,
  payment_date: new Date().toISOString().split('T')[0],
  type: paymentType,
  reference: `Paiement ${parsedData.payment_method}`,
  notes: `Paiement automatique via ${parsedData.payment_method}`
};

console.log('Données paiement préparées:', JSON.stringify(paymentData, null, 2));

return {
  invoice_id: invoiceData.id,
  payment_data: paymentData
};

